#!/usr/bin/env bash
# Work QY2 (X201, X174): the 726 open YTD_QUARTER_MISMATCH findings of the NEW members (snapshot 2026-11-17 21C).
# Run from the repo root on the live machine with the QY2 code merged, while no other writer holds the DB.
# Quarantine and filing ids are deterministic (from the snapshot).
set -euo pipefail
F="python -m financials --data-dir data"

# --- 1. Rule LEVEL_OF_ROUNDING_SLIP (X201): rescale the 16 filings that declared the wrong LevelOfRounding (12 entities,
#        incl. 5 Nifty 500 seed filings already settled by PDF corrections: their PDF-corrected values are kept), then the
#        YTD re-audit of those entity-scopes. Snapshot dry run: closes 63 findings (MAMATA 24, ESSARSHPNG 13, SADBHAV 12,
#        NAVNETEDUL 5, PARKHOTELS 5, IMPAL 4) and raises 2 at the right scale (PARKHOTELS FY26 consolidated revenue /
#        total income, 0.55%: left open, no FY26 PDF in the listings).
$F rescale-level-slips --dry-run
$F rescale-level-slips

# --- 2. Decision B: values read from the statutory results PDFs (nsearchives, linked from the vaulted NSE listings),
#        35 corrections on 14 filing groups (ops/live/QY2_corrections.json: printed line, page, reads).
#        Each closes its findings (30: ASMS 8, BHARATRAS 6, SILINV 6, STALLION 4, DHANBANK 4, SHIVAMAUTO 2) as CORRECTED.
python - <<'PY'
import json
from financials.db import connect
from financials.admin import correct_from_pdf
con = connect("data/market.duckdb")
try:
    for g in json.load(open("ops/live/QY2_corrections.json")):
        for qid in (g["quarantine_ids"] or [None]):
            correct_from_pdf(con, g["filing_id"], g["corrections"], evidence_url=g["evidence_url"],
                             evidence_page=g["evidence_page"], evidence_text=g["evidence_text"], reads=g["reads"],
                             note=g["note"], quarantine_id=qid)
finally:
    con.close()
PY

# --- 3. Decision A precedent (as the Nifty 500 review, 2026-11-15): breaks the company's statement explains (restated /
#        regrouped earlier quarter, merger / demerger / amalgamation, discontinued operations, change of accounting policy,
#        presentation of other income, whole-crore rounding, the company's own arithmetic), each with its evidence:
#        172 findings (PDF-checked 132, XBRL evidence 40).
R() { $F quarantine resolve --id "$1" --action ACCEPT --note "$2"; }
